name = #{name}, content = #{content}, duration = #{duration}, pass_point = #{passPoint}, total_point = #{totalPoint}, status = #{status}, summary = #{summary}, is_visible = #{isVisible}, answer_sheet = #{answerSheet}, group_id = #{groupId}, is_subjective = #{isSubjective}, creator = #{creator}, paper_type = #{paperType}, field_id = #{fieldId}, validsource = #{validsource}, validdpt = #{validdpt}, exam_count = #{examCount}, answer_hide = #{answerHide}, update_time = #{updateTime}
