SELECT 
    id, name, content, duration, pass_point, total_point, status, summary,
    is_visible, answer_sheet, group_id, is_subjective, creator,
    paper_type, field_id, validsource, validdpt, exam_count, answer_hide,
    create_time, update_time
FROM et_exam_paper


        AND name LIKE CONCAT('%', #{name}, '%')


        AND status = #{status}


        AND validdpt = #{validdpt}


        AND validsource = #{validsource}


        AND paper_type = #{paperType}


ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

